head.script:
scwin.trigger1_onclick = function(e) {
	if (WebSquare._xv !== "SP5") { requires("uiplugin.popup"); }
	var options = {
		id: "popup2",
		type: "wframePopup",
		width: 900 + "px",
		height: 600 + "px",
		top: 100 + "px",
		left: 100 + "px",
		modal: false,
		useModalStack: true,
		className: "",
		style: "",
		resizable: true,
		status: false,
		menubar: false,
		scrollbars: false,
		title: false,
		useMaximize: true
	};
	$p.openPopup("/sample/common_link/wframe_isPopup_popupMain_531_(WSQ-4627)_sub.xml", options);
};

scwin.onpageload = function() {
	localStorage.removeItem("log");
};
